tool_input.content:
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Dbg {
    public interface AgentIface1 {
        void process(Number n);
    }

    public interface AgentIface2 {
        void process(Number n);
    }

    public static class Ambiguous implements AgentIface1, AgentIface2 {
        public void process(final Number n) {
        }
    }

    public static void main(final String[] a) throws Exception {
        for (final Method m : Ambiguous.class.getDeclaredMethods()) {
            System.out.println("declared: " + m);
        }
        final List<Class<?>> supers = new ArrayList<Class<?>>();
        Class<?> c = Ambiguous.class.getSuperclass();
        while (c != null) {
            supers.add(c);
            c = c.getSuperclass();
        }
        System.out.println("supers: " + supers);
        System.out.println("interfaces: " + Arrays.toString(Ambiguous.class.getInterfaces()));
    }
}
